import sys,heapq
it=iter(map(int,sys.stdin.buffer.read().split()));n=next(it);m=next(it);g=[[] for _ in range(n)]
for _ in range(m):
 u=next(it)-1;v=next(it)-1;w=next(it);g[u].append((v,w));g[v].append((u,w))
d=[10**30]*n;d[0]=0;h=[(0,0)]
while h:
 x,u=heapq.heappop(h)
 if x!=d[u]: continue
 for v,w in g[u]:
  y=max(x,w)
  if y<d[v]: d[v]=y;heapq.heappush(h,(y,v))
print(-1 if d[-1]==10**30 else d[-1])

